    out = []

    for r in range(r0, r1 + 1):
        target = grid[r][c1 + 1:]
        best_score, best_prefix = -1, None
        for rr in range(H):
            if rr == r or any(v == 8 for v in grid[rr]):
                continue
            for start in range(W - len(target) + 1):
                end = start + len(target)
                if start < c0 or end > W:
                    continue
                candidate = grid[rr][start:end]
                score = sum(a == b for a, b in zip(target, candidate))
                if score > best_score:
                    best_score = score
                    best_prefix = grid[rr][start - (c1 + 1 - c0):start]
        if best_prefix is None or len(best_prefix) != c1 - c0 + 1:
            best_prefix = [0] * (c1 - c0 + 1)
        out.append(best_prefix)
    return out
